/**
 * @distilled.cloud/openrouter — OpenRouter API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model in
 * `.generated-specs` (written by `scripts/convert.ts` from the OpenAPI
 * document mirrored into `specs/`). Everything else in this folder is
 * hand-written.
 *
 * Operations sit on the package root (`OpenRouter.getModels`). The
 * hand-written modules are re-exported by NAME: the generated service module
 * star-exported below also exports error classes (`BadRequest`,
 * `PaymentRequired`, …), and two star exports of the same name silently drop
 * it. Explicit named exports take precedence, so the shared classes stay at
 * the root while the service-local ones remain reachable via the
 * `./openrouter` subpath.
 *
 * @example
 * ```ts
 * import * as OpenRouter from "@distilled.cloud/openrouter";
 *
 * const models = yield* OpenRouter.getModels({});
 * ```
 */
export {
  DEFAULT_API_BASE_URL,
  type Config,
  Credentials,
  CredentialsFromEnv,
  credentials,
} from "./credentials.ts";
export {
  BadGateway,
  BadRequest,
  Conflict,
  ConfigError,
  Forbidden,
  GatewayTimeout,
  InternalServerError,
  Locked,
  NotFound,
  ServiceUnavailable,
  TooManyRequests,
  Unauthorized,
  UnprocessableEntity,
  HTTP_STATUS_MAP,
  DEFAULT_ERRORS,
  API_ERRORS,
  PaymentRequired,
  UnknownOpenRouterError,
  OpenRouterParseError,
  type ClientErrors,
  type DefaultErrors,
} from "./errors.ts";
export * as T from "./traits.ts";
export {
  OpenRouterProtocol,
  type OpenRouterOpError,
  type OpenRouterOpContext,
} from "./protocol.ts";
export * as Retry from "./retry.ts";
export * from "./services/openrouter.ts";
